export default function Footer() {
  const pathname = usePathname();
  const currentIndex = pageOrder.findIndex((p) => p.href === pathname);
  const next = pageOrder[(currentIndex + 1) % pageOrder.length];

  return (
    <footer className="relative overflow-hidden bg-green-dark pt-20 pb-10 lg:min-h-159">
      <FooterArt />

      <div className="relative z-10 max-w-360 mx-auto px-4 sm:px-6 h-full text-center flex flex-col items-center">
        <div className="inline-flex items-center border border-white/25 rounded-full px-4 py-1.5 mb-6">
          <span className="text-white text-[11px] font-semibold tracking-[0.15em] uppercase">
            Up Next
          </span>
        </div>

        <h2 className="font-heading font-bold text-gold text-[56px] leading-tight mb-8 max-w-250">
          {next.title}
        </h2>

        <Link
          href={next.href}
          aria-label={`Go to ${next.title}`}
          className="inline-flex hover:opacity-80 transition-opacity"
        >
          <NextArrowIcon />
        </Link>

        <div className="mt-25 pt-16 text-[13px] text-white/70">
          <p>
            <span className="text-gold font-semibold">DREEF</span>
            {" — Distributed Renewable Energy Enhancement Facility"}
          </p>
          <p>
            183 Moshood Olugbani, Victoria Island, Lagos ·{" "}
            <a
              href="mailto:pmt@dreef.org"
              className="hover:text-white transition-colors"
            >
              pmt@dreef.org
            </a>
          </p>

          <p className="text-xs mt-15 text-white/40">
            DRELT Master Handbook · Abridged Interactive Version · For
            authorised use within InfraCredit&apos;s DRE pipeline
          </p>
        </div>
      </div>
    </footer>
  );
}
